for (int i = 0; i < 4; ++i) {
    auto wp = c->vertex(i)->point();
    coords[i][0] = wp.x();
    coords[i][1] = wp.y();
    coords[i][2] = wp.z();
    coords[i][3] = wp.weight();
}

LiftedPoint p0 = lifted_point(coords[0][0], coords[0][1], coords[0][2], coords[0][3]);
LiftedPoint p1 = lifted_point(coords[1][0], coords[1][1], coords[1][2], coords[1][3]);
LiftedPoint p2 = lifted_point(coords[2][0], coords[2][1], coords[2][2], coords[2][3]);
LiftedPoint p3 = lifted_point(coords[3][0], coords[3][1], coords[3][2], coords[3][3]);

HyperPlane h(p0, p1, p2, p3);

std::array<double, 4> normal;
for (int i = 0; i < 4; ++i) {
    normal[i] = h.coefficient(i);
}

double nx = normal[0];
double ny = normal[1];
double nz = normal[2];
double nw = normal[3];

Vector velocity_vector(nx, ny, nz);
if (nw != 0.0) {
    velocity_vector = velocity_vector / (-nw);
}

return velocity_vector;

